function indicesNearKey(nums: number[], key: number, k: number): number[] {
  const n = nums.length, out: number[] = [];
  for (let i = 0; i < n; i++) {
    for (let j = Math.max(0, i - k); j <= Math.min(n - 1, i + k); j++) {
      if (nums[j] === key) { out.push(i); break; }
    }
  }
  return out;
}

