function indicesNearKey(nums: number[], key: number, k: number): number[] {
  const n = nums.length, out: number[] = [];
  let next = 0; // smallest index not emitted yet
  for (let j = 0; j < n; j++) {
    if (nums[j] !== key) continue;
    const end = Math.min(n - 1, j + k);
    for (let i = Math.max(next, j - k); i <= end; i++) out.push(i);
    next = Math.max(next, end + 1);
  }
  return out;
}

